const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const a = [0, ...tok.slice(2, 2 + n)];
const adj = Array.from({ length: n + 1 }, () => []);
const p0 = 2 + n;
for (let i = 0; i < n - 1; i++) {
  const u = tok[p0 + 2 * i], v = tok[p0 + 2 * i + 1];
  adj[u].push(v); adj[v].push(u);
}
const parent = new Array(n + 1).fill(0), depth = new Array(n + 1).fill(0);
parent[1] = -1;
const order = [1];
for (let i = 0; i < order.length; i++) {
  const v = order[i];
  for (const to of adj[v]) if (to !== parent[v]) { parent[to] = v; depth[to] = depth[v] + 1; order.push(to); }
}
const size = new Array(n + 1).fill(1), heavy = new Array(n + 1).fill(0);
for (let i = n - 1; i >= 0; i--) { const v = order[i]; if (parent[v] > 0) size[parent[v]] += size[v]; }
for (let i = 1; i < n; i++) {
  const v = order[i], p = parent[v];
  if (heavy[p] === 0 || size[v] > size[heavy[p]]) heavy[p] = v;
}
const head = new Array(n + 1).fill(0), pos = new Array(n + 1).fill(0);
let cnt = 0;
for (const v of order) {
  if (v === 1 || heavy[parent[v]] !== v) {
    for (let u = v; u; u = heavy[u]) { head[u] = v; pos[u] = cnt++; }
  }
}
const NEG = -Infinity;
const t = new Array(2 * n).fill(NEG);
for (let v = 1; v <= n; v++) t[n + pos[v]] = a[v];
for (let i = n - 1; i > 0; i--) t[i] = Math.max(t[2 * i], t[2 * i + 1]);
function segQuery(l, r) {
  let res = NEG;
  for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
    if (l & 1) res = Math.max(res, t[l++]);
    if (r & 1) res = Math.max(res, t[--r]);
  }
  return res;
}
const out = [];
let p = p0 + 2 * (n - 1);
for (let k = 0; k < q; k++) {
  if (tok[p] === 1) {
    let i = n + pos[tok[p + 1]];
    t[i] = tok[p + 2];
    for (i >>= 1; i >= 1; i >>= 1) t[i] = Math.max(t[2 * i], t[2 * i + 1]);
    p += 3;
  } else {
    let u = tok[p + 1], v = tok[p + 2];
    p += 3;
    let best = NEG;
    while (head[u] !== head[v]) {
      if (depth[head[u]] < depth[head[v]]) { const x = u; u = v; v = x; }
      best = Math.max(best, segQuery(pos[head[u]], pos[u] + 1));
      u = parent[head[u]];
    }
    if (depth[u] > depth[v]) { const x = u; u = v; v = x; }
    best = Math.max(best, segQuery(pos[u], pos[v] + 1));
    out.push(best);
  }
}
console.log(out.join("\n"));

