import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static int[] t;

    static int segQuery(int l, int r) {
        int res = Integer.MIN_VALUE;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) res = Math.max(res, t[l++]);
            if ((r & 1) == 1) res = Math.max(res, t[--r]);
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        int[] a = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            in.nextToken();
            a[i] = (int) in.nval;
        }
        List<Integer>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            adj[u].add(v);
            adj[v].add(u);
        }
        int[] parent = new int[n + 1], depth = new int[n + 1], order = new int[n];
        int head0 = 0, tail = 0;
        parent[1] = -1;
        order[tail++] = 1;
        while (head0 < tail) {
            int v = order[head0++];
            for (int to : adj[v]) if (to != parent[v]) { parent[to] = v; depth[to] = depth[v] + 1; order[tail++] = to; }
        }
        int[] size = new int[n + 1], heavy = new int[n + 1];
        Arrays.fill(size, 1);
        for (int i = n - 1; i >= 1; i--) size[parent[order[i]]] += size[order[i]];
        for (int i = 1; i < n; i++) {
            int v = order[i], p = parent[v];
            if (heavy[p] == 0 || size[v] > size[heavy[p]]) heavy[p] = v;
        }
        int[] head = new int[n + 1], pos = new int[n + 1];
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            int v = order[i];
            if (v == 1 || heavy[parent[v]] != v) {
                for (int u = v; u != 0; u = heavy[u]) { head[u] = v; pos[u] = cnt++; }
            }
        }
        t = new int[2 * n];
        Arrays.fill(t, Integer.MIN_VALUE);
        for (int v = 1; v <= n; v++) t[n + pos[v]] = a[v];
        for (int i = n - 1; i > 0; i--) t[i] = Math.max(t[2 * i], t[2 * i + 1]);
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            in.nextToken();
            int type = (int) in.nval;
            in.nextToken();
            int x = (int) in.nval;
            in.nextToken();
            int y = (int) in.nval;
            if (type == 1) {
                int i = n + pos[x];
                t[i] = y;
                for (i >>= 1; i >= 1; i >>= 1) t[i] = Math.max(t[2 * i], t[2 * i + 1]);
            } else {
                int u = x, v = y, best = Integer.MIN_VALUE;
                while (head[u] != head[v]) {
                    if (depth[head[u]] < depth[head[v]]) { int s = u; u = v; v = s; }
                    best = Math.max(best, segQuery(pos[head[u]], pos[u] + 1));
                    u = parent[head[u]];
                }
                if (depth[u] > depth[v]) { int s = u; u = v; v = s; }
                best = Math.max(best, segQuery(pos[u], pos[v] + 1));
                out.append(best).append('\n');
            }
        }
        System.out.print(out);
    }
}

