#include <bits/stdc++.h>
using namespace std;
int n;
vector<int> t;

int segQuery(int l, int r) {
    int res = INT_MIN;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if (l & 1) res = max(res, t[l++]);
        if (r & 1) res = max(res, t[--r]);
    }
    return res;
}

int main() {
    int q;
    scanf("%d %d", &n, &q);
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> parent(n + 1, 0), depth(n + 1, 0), order{1};
    parent[1] = -1;
    for (size_t i = 0; i < order.size(); i++) {
        int v = order[i];
        for (int to : adj[v]) if (to != parent[v]) { parent[to] = v; depth[to] = depth[v] + 1; order.push_back(to); }
    }
    vector<int> sz(n + 1, 1), heavy(n + 1, 0);
    for (int i = n - 1; i >= 1; i--) sz[parent[order[i]]] += sz[order[i]];
    for (int i = 1; i < n; i++) {
        int v = order[i], p = parent[v];
        if (heavy[p] == 0 || sz[v] > sz[heavy[p]]) heavy[p] = v;
    }
    vector<int> head(n + 1), pos(n + 1);
    int cnt = 0;
    for (int v : order)
        if (v == 1 || heavy[parent[v]] != v)
            for (int u = v; u; u = heavy[u]) { head[u] = v; pos[u] = cnt++; }
    t.assign(2 * n, INT_MIN);
    for (int v = 1; v <= n; v++) t[n + pos[v]] = a[v];
    for (int i = n - 1; i > 0; i--) t[i] = max(t[2 * i], t[2 * i + 1]);
    while (q--) {
        int type, x, y;
        scanf("%d %d %d", &type, &x, &y);
        if (type == 1) {
            int i = n + pos[x];
            t[i] = y;
            for (i >>= 1; i >= 1; i >>= 1) t[i] = max(t[2 * i], t[2 * i + 1]);
        } else {
            int u = x, v = y, best = INT_MIN;
            while (head[u] != head[v]) {
                if (depth[head[u]] < depth[head[v]]) swap(u, v);
                best = max(best, segQuery(pos[head[u]], pos[u] + 1));
                u = parent[head[u]];
            }
            if (depth[u] > depth[v]) swap(u, v);
            best = max(best, segQuery(pos[u], pos[v] + 1));
            printf("%d\n", best);
        }
    }
    return 0;
}
